{
  "returncode": 0,
  "output_head": "/* The Radar screen (knowledge-base/features/ops-control-panel.md §6). Dark by default; light follows html[data-theme].
   The sweep is slow and smooth on purpose (60 s a turn). Typefaces are the console's own (../styles/tokens.css). */

.radar-screen {
  --radar-ink: #f8fafc;
  --radar-ink-2: #ffffff;
  --radar-muted: #cbd5e1;
  --radar-dim: #94a3b8;
  --radar-faint: #7b8ba3;
  --radar-accent: #2563eb;
  --radar-amber: #ffb547;
  --radar-amber-ink: #ffc46b;
  --radar-lime: #93c5fd;
  --radar-resolved: #60a5fa;
  --radar-line: rgba(59, 130, 246, 0.16);
  --radar-detail: #93c5fd;
  --radar-stale-ink: #ffd9a0;
  --radar-on-pressed: #eff6ff;
  --radar-pill-ack: #bfdbfe;
  --radar-ring-label: rgba(147, 197, 253, 0.75);
  /* Flat page ground — no full-screen gradient; the scope disc keeps its own fill. */
  --radar-ground: #0a0f1a;
  --radar-head-bg: #101828;
  --radar-panel-bg: #101828;
  --radar-panel-hover: #16233a;
  --radar-disc: radial-gradient(circle, rgba(30, 58, 138, 0.45) 0%, rgba(16, 24, 40, 0.75) 55%, rgba(10, 15, 26, 0.95) 100%);
  --radar-axis-bg: rgba(16, 24, 40, 0.92);
  --radar-telemetry-bg: #101828;
  --radar-crt: none;
  --radar-sweep-blend: screen;
  --radar-display: "IBM Plex Sans", system-ui, sans-serif;
  --radar-mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
  position: relative;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  background: var(--radar-ground);
  color: var(--radar-ink);
  font-family: var(--radar-display);
  animation: none;
}
.radar-screen:fullscreen { overflow: auto; }
.radar-screen button { font-family: inherit; }
.radar-screen button:focus-visible, .radar-screen a:focus-visible { outline: 2px solid var(--radar-accent); outline-offset: 2px; }

/* The screen's own header — it stands alone in full screen. */
.radar-head { display: flex; align-items: center; gap: 20px; padding: 12px 32px; border-bottom: 1px solid var(--radar-line); background: var(--radar-head-bg); white-space: nowrap; }
.radar-head > * { flex-shrink: 0; }
.radar-head > .radar-head-gap { flex-shrink: 1; min-width: 0; }
/* the tenant's logo leads the header only in full screen, where the console's own header is gone */
.radar-head-logo { display: none; }
.radar-screen:fullscreen .radar-head-logo { display: flex; align-items: center; padding-right: 20px; border-right: 1px solid var(--radar-line); }
.radar-head-logo img { height: 30px; width: auto; max-width: 140px; object-fit: contain; }
.radar-head-gap { flex-grow: 1; }
/* The app header above already carries the airline's mark: the Radar's own shows only full screen, like the dCortex wordmark. */
.radar-head-tenant { display: none; height: 28px; width: 28px; border-radius: 8px; object-fit: cover; }
.radar-screen:fullscreen .radar-head-tenant { display: block; }
.radar-brand { display: flex; align-items: center; gap: 12px; line-height: 1.05; }
.radar-brand-title { font-family: var(--radar-mono); font-size: 13px; font-weight: 600; letter-spacing: 3px; color: var(--radar-muted); white-space: nowrap; }
.radar-brand-ring { fill: none; stroke: var(--radar-accent); stroke-width: 1.5; }
.radar-brand-ring--inner { stroke: rgba(59, 130, 246, 0.5); stroke-width: 1.2; }
.radar-brand-beam { stroke: var(--radar-accent); stroke-width: 2; }
.radar-brand-blip { fill: var(--radar-amber); }
.radar-feed-pill { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 999px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1px; white-space: nowrap; }
.radar-feed-pill--stale { border-color: var(--radar-amber); color: var(--radar-stale-ink); }
.radar-feed-pill--stale .radar-live-dot { background: var(--radar-amber); box-shadow: 0 0 10px var(--radar-amber); }
.radar-live-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--radar-accent); box-shadow: 0 0 10px var(--radar-accent); animation: radar-livedot 1.2s infinite; }
.radar-clock { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.1; font-family: var(--radar-mono); }
.radar-clock-time { font-size: 20px; font-weight: 600; }
.radar-clock--utc .radar-clock-time { color: var(--radar-dim); }
.radar-clock-label { font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-head-button { min-height: 36px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-screen:fullscreen .radar-head-button { display: none; }
.radar-modes { display: inline-flex; align-items: stretch; margin-left: auto; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; overflow: hidden; background: transparent; }
.radar-modes .radar-mode { min-height: 36px; padding: 6px 14px; border: 0; border-radius: 0; background: transparent; color: var(--radar-muted); font-family: ",
  "output_tail": "-radar-accent); color: var(--radar-on-pressed); }

.radar-locked { display: flex; flex-direction: column; gap: 10px; padding: 16px 18px; border-radius: 12px; border: 1px solid rgba(255, 181, 71, 0.5); background: linear-gradient(135deg, rgba(255, 181, 71, 0.1), rgba(59, 130, 246, 0.05)); }
.radar-locked-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-family: var(--radar-mono); font-size: 11px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-locked-mark { color: var(--radar-amber-ink); }
.radar-locked-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding-right: 36px; }
.radar-locked-title { font-size: 21px; font-weight: 600; line-height: 1.2; }
.radar-locked-kind { font-size: 14px; font-weight: 400; line-height: 1.4; color: var(--radar-muted); }
.radar-locked-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 18px; }
.radar-locked-fact-label { display: block; margin-bottom: 2px; font-family: var(--radar-mono); font-size: 10px; letter-spacing: 0.8px; color: var(--radar-dim); }
.radar-locked-fact-value { font-size: 15px; }
.radar-locked-detail { font-size: 14px; line-height: 1.4; color: var(--radar-muted); }
.radar-locked-actions { display: flex; align-items: center; gap: 8px; }
.radar-primary { min-height: 44px; padding: 10px 16px; border: 1px solid var(--radar-accent); border-radius: 8px; background: var(--radar-accent); color: #ffffff; font-size: 13px; font-weight: 700; letter-spacing: 1.5px; cursor: pointer; }
.radar-secondary { display: inline-flex; align-items: center; min-height: 44px; box-sizing: border-box; padding: 10px 16px; border: 1px solid rgba(59, 130, 246, 0.45); border-radius: 8px; color: var(--radar-ink); font-size: 13px; font-weight: 600; letter-spacing: 1.5px; text-decoration: none; }
button.radar-secondary { background: transparent; cursor: pointer; font-family: inherit; }
button.radar-secondary:disabled { opacity: 0.6; cursor: default; }
.radar-secondary:hover { background: rgba(59, 130, 246, 0.08); }
button.radar-secondary { background: none; font-family: inherit; cursor: pointer; }
button.radar-secondary:hover { background: rgba(59, 130, 246, 0.08); }
